ROOT=Path(__file__).resolve().parents[1];CACHE=ROOT/'tmp/cad-next-search/waam';DATA=ROOT/'data/web-cad-fem-variety';OUT=DATA/'waam';shutil.copytree(CACHE,OUT,dirs_exist_ok=True)
f=next(OUT.rglob('*.STEP'));s=cq.importers.importStep(str(f)).val();b=s.BoundingBox();out={'cad':{'file':str(f.relative_to(DATA)),'valid':s.isValid(),'solids':len(s.Solids()),'faces':len(s.Faces()),'bounds_mm':[b.xmin,b.ymin,b.zmin,b.xmax,b.ymax,b.zmax]},'results':[]};assert s.isValid()
